#!/usr/bin/env node
/* eslint-env node */
/**
 * build-techniques-index.js — generate the client-side technique index (v7.20.128)
 *
 * ONE VOCABULARY. The outline's technique picker must never hand-type a roster: WML already
 * carries three lists that drift against each other —
 *   1. MADFATHER'S CROPS          — the taught mnemonic (knowledge-hub.md:279)
 *   2. _DEVICE_MENU_DATA          — 26 construction templates (wml-assessment.js:1045)
 *   3. table-of-techniques.md     — 245 entries, GENERATED by sophicly-notes
 * (3) is the source of truth for a technique's NAME and CODE. This script reads it and emits
 * frontend/wml-techniques-index.js so the picker's tier 2 IS the table, not a copy of it.
 *
 * TIER 1 is authored here, not read from the table, because the four groups are the PROTOCOL's
 * teaching structure (aqa/language2/planning/protocol-b-planning.md:619-627 — "offer 2-3 to
 * start, EXACTLY these groups"), not the table's taxonomy. But every tier-1 name is RESOLVED
 * against the table and the build FAILS LOUD on a miss — so a rename in the table can never
 * silently fork the picker's vocabulary from the taught one.
 *
 * Run: node bin/build-techniques-index.js   (wired into bin/pre-ship-check.sh via --check)
 */
'use strict';

const fs = require('fs');
const path = require('path');

const ROOT = path.resolve(__dirname, '..');
const TABLE = path.join(ROOT, 'protocols/shared/reference/table-of-techniques.md');
const OUT = path.join(ROOT, 'frontend/wml-techniques-index.js');
const CHECK_ONLY = process.argv.includes('--check');

// ── TIER 1 — the protocol's device groups, verbatim from protocol-b-planning.md:619-627 ──
// `name` is what the STUDENT sees (the taught word). `resolve` is the table entry it must
// map to when the taught word and the canonical entry differ.
//   - "Triadic structure" is the taught word; the table's entry is `Tricolon` (Tr). There is
//     no `### Triadic…` heading (grepped: zero). Show the taught word, resolve to Tricolon.
//   - "Repetition / anaphora" is ONE taught item in the protocol though the table holds two
//     entries (Re, An). The protocol wins: one chip, resolved to Repetition.
// The protocol's groups deliberately OMIT Facts (it lives in opener D) and ADD anaphora —
// so tier 1 is 14 items, not the mnemonic's 15. Protocol wins over the mnemonic.
const TIER1 = [
    { group: 'Sound', items: [
        { name: 'Alliteration', hint: 'repeated consonants' },
        { name: 'Assonance', hint: 'repeated vowels' },
        { name: 'Sibilance', hint: "repeated 's' sounds" },
        { name: 'Onomatopoeia', hint: 'sound words' },
    ] },
    { group: 'Comparison', items: [
        { name: 'Metaphor', hint: 'one thing IS another' },
        { name: 'Simile', hint: "'like' / 'as'" },
        { name: 'Personification', hint: 'human qualities to non-human' },
    ] },
    { group: 'Structural', items: [
        { name: 'Triadic structure', resolve: 'Tricolon', hint: 'power of three' },
        { name: 'Rhetorical question', hint: '' },
        { name: 'Direct address', hint: '' },
        { name: 'Contrast', hint: 'opposites together' },
    ] },
    { group: 'Intensity', items: [
        { name: 'Hyperbole', hint: 'deliberate exaggeration' },
        { name: 'Emotive language', hint: '' },
        { name: 'Repetition / anaphora', resolve: 'Repetition', hint: '' },
    ] },
];

// ── Templates the device menu can construct, keyed by the technique they build ──
// The picker offers "show me how to build one" ONLY for these. Names must match
// _DEVICE_MENU_DATA group/item names in wml-assessment.js — verified by fieldid-harness.
const TEMPLATED = ['Metaphor', 'Simile', 'Personification', 'Hyperbole', 'Tricolon', 'Anaphora',
    'Parallelism', 'Chiasmus', 'Alliteration', 'Rhetorical question'];

function parseTable(md) {
    const entries = [];
    let cat = null;
    for (const line of md.split('\n')) {
        const m2 = line.match(/^## (.+)$/);
        if (m2) { cat = m2[1].trim(); continue; }
        const m3 = line.match(/^### (.+?)\s+`([^`]+)`\s*$/);
        if (m3) entries.push({ n: m3[1].trim(), c: m3[2], g: cat });
    }
    return entries;
}

function build() {
    if (!fs.existsSync(TABLE)) {
        console.error('FAIL: technique table not found at ' + path.relative(ROOT, TABLE));
        process.exit(1);
    }
    const entries = parseTable(fs.readFileSync(TABLE, 'utf8'));
    if (entries.length < 200) {
        console.error('FAIL: parsed only ' + entries.length + ' techniques — the table format changed.');
        process.exit(1);
    }

    const byName = new Map(entries.map(e => [e.n.toLowerCase(), e]));
    const codes = new Set(entries.map(e => e.c));
    if (codes.size !== entries.length) {
        console.error('FAIL: duplicate technique codes in the table.');
        process.exit(1);
    }

    // Resolve tier 1 against the table — FAIL LOUD, never fall back to the taught word.
    const misses = [];
    const tier1 = TIER1.map(grp => ({
        group: grp.group,
        items: grp.items.map(it => {
            const target = (it.resolve || it.name).toLowerCase();
            const hit = byName.get(target);
            if (!hit) { misses.push(it.name + (it.resolve ? ' (→ ' + it.resolve + ')' : '')); return null; }
            return { name: it.name, code: hit.c, canonical: hit.n, hint: it.hint || '' };
        }),
    }));
    if (misses.length) {
        console.error('FAIL: tier-1 technique(s) have no entry in table-of-techniques.md:');
        misses.forEach(m => console.error('  - ' + m));
        console.error('Add the entry via sophicly-notes\' build-techniques-md.js, or fix the resolve alias.');
        process.exit(1);
    }

    // Integrity: every tier-1 item must carry a real code, and codes must be distinct. Without
    // this, a field-name typo in the resolver emits `code: undefined` for all 14 and the picker
    // ships a vocabulary that resolves to nothing — silent, and invisible to node --check.
    const tier1Flat = tier1.flatMap(g => g.items);
    const bad = tier1Flat.filter(i => !i || !i.code || !codes.has(i.code));
    if (bad.length) {
        console.error('FAIL: ' + bad.length + ' tier-1 item(s) resolved to no valid table code.');
        process.exit(1);
    }
    const tier1Codes = new Set(tier1Flat.map(i => i.code));
    if (tier1Codes.size !== tier1Flat.length) {
        console.error('FAIL: two tier-1 items resolve to the same table code.');
        process.exit(1);
    }
    const templated = TEMPLATED.map(n => {
        const hit = byName.get(n.toLowerCase());
        if (!hit) { console.error('FAIL: templated technique "' + n + '" has no table entry.'); process.exit(1); }
        return hit.c;
    });

    const banner = '// GENERATED by bin/build-techniques-index.js from\n'
        + '// protocols/shared/reference/table-of-techniques.md — DO NOT EDIT BY HAND.\n'
        + '// Regenerate: node bin/build-techniques-index.js\n'
        + '// ' + entries.length + ' techniques · tier 1 = ' + tier1Codes.size + ' taught devices (protocol-b-planning.md:619-627)\n';

    const body = banner + '(function () {\n'
        + '    window.WML_TECHNIQUES = {\n'
        + '        tier1: ' + JSON.stringify(tier1) + ',\n'
        + '        all: ' + JSON.stringify(entries.map(e => ({ n: e.n, c: e.c, g: e.g }))) + ',\n'
        + '        templated: ' + JSON.stringify(templated) + ',\n'
        + '    };\n'
        + '})();\n';

    if (CHECK_ONLY) {
        const cur = fs.existsSync(OUT) ? fs.readFileSync(OUT, 'utf8') : '';
        if (cur !== body) {
            console.error('FAIL: frontend/wml-techniques-index.js is stale.');
            console.error('The technique table changed but the index was not regenerated.');
            console.error('Run: node bin/build-techniques-index.js');
            process.exit(1);
        }
        console.log('techniques-index: up to date (' + entries.length + ' techniques, tier 1 resolved).');
        return;
    }

    fs.writeFileSync(OUT, body);
    console.log('techniques-index: wrote ' + path.relative(ROOT, OUT));
    console.log('  ' + entries.length + ' techniques · ' + tier1Codes.size + ' tier-1 · ' + templated.length + ' templated');
    tier1.forEach(g => console.log('  ' + g.group + ': ' + g.items.map(i => i.name + ' `' + i.code + '`').join(' · ')));
}

build();
